type DeliveryState = 'authorizing'|'preparing-candidate'|'writing'|'verifying'|'reviewing'|'repairing'|'cancelling'|'merge-ready'|'decision-required'|'failed-safely'
type SnapshotIdentity = { headSha:string; treeOid:string; statusDigest:string }
type CandidateIdentity = { base:SnapshotIdentity; candidateTreeOid:string; diffSha256:string }
type VerificationPolicy = { command:['bash','scripts/verify.sh']; closure:Array<{path:string;mode:string;blobOid:string}>; environmentDigest:string; digest:string }
type VerificationReceipt = { candidateTreeOid:string; policyDigest:string; status:'passed'|'failed'|'missing'|'timeout'|'mutated'; exitCode?:number; durationMs:number; outputSha256:string; redactedFailureOutputTail?:string; verifiedTreeOid?:string }
type ReviewReceipt = { candidateTreeOid:string; reviewerProfileDigest:string; reviewInputDigest:string; reviewOutputDigest:string; verdict:'proud'|'needs-attention'; findings:Array<{severity:'must-fix'|'should-fix'|'optional';code:string;summary:string;evidence:string}> }
type DeliveryAttemptRecord = { attempt:number; candidateTreeOid:string; writerProfileDigest:string; writerProcessOutputDigest:string; verification?:VerificationReceipt; review?:ReviewReceipt; invalidatedAt?:string }
type LeaseRecord = { leaseNonce:string; runId:string; pid:number; processStart:string; root:string }
type DeliveryRunV1 = { schemaVersion:1; runId:string; root:string; state:DeliveryState; authority:{requestId:string;source:'interactive';request:string;requestDigest:string}; primaryProfileDigest:string; base?:SnapshotIdentity; candidate?:CandidateIdentity; candidateRoot?:string; verificationPolicy?:VerificationPolicy; baselineVerification?:VerificationReceipt; verification?:VerificationReceipt; review?:ReviewReceipt; expectedReviewerProfileDigest?:string; expectedReviewInputDigest?:string; repairCount:number; failureSignatures:string[]; attempts:DeliveryAttemptRecord[]; pendingChild?:{role:string;readyPath:string;preparedAt:string}; child?:{role:'writer'|'repair'|'verifier'|'reviewer';pid:number;processStart:string;startedAt:string}; childExits:Array<{role:string;observedAt:string;exitCode?:number;timedOut:boolean;recovery?:boolean}>; finalTupleDigest?:string; terminalReason?:string }

The active lease is mutable and nonce-fenced. Each run owns a separate append-only evidence history inside its durable manifest. Only markMergeReady recomputes and validates the canonical authority/base/policy/baseline/writer/candidate/verifier/reviewer/exit/repair tuple before persisting MERGE READY.
